/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dlascl = require( './../lib/dlascl.js' );


// FIXTURES //

var COL_MAJOR_GENERAL = require( './fixtures/general_column_major.json' );
var ROW_MAJOR_GENERAL = require( './fixtures/general_row_major.json' );
var COL_MAJOR_UPPER = require( './fixtures/upper_column_major.json' );
var ROW_MAJOR_UPPER = require( './fixtures/upper_row_major.json' );
var COL_MAJOR_LOWER = require( './fixtures/lower_row_major.json' );
var ROW_MAJOR_LOWER = require( './fixtures/lower_row_major.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlascl, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 10', function test( t ) {
	t.strictEqual( dlascl.length, 10, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var i;

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlascl( value, 'general', 0, 0, 1, 1, 0, 0, new Float64Array(), 1 );
		};
	}
});

